def blade(sign):
    secs=[]
    for i,z in enumerate([2,50,100]):
        ang=[40,25,15][i]*sign
        c=[12,10,7][i]; t=[3,2,1.2][i]
        wp=cq.Workplane("XY").workplane(offset=z*sign).transformed(rotate=(0,0,ang)).rect(c,t)
        secs.append(wp.val())
    return cq.Solid.makeLoft([cq.Wire.assembleEdges(s.Edges()) if hasattr(s,'Edges') else s for s in secs])
def sec(z,ang,c,t):
    return cq.Workplane("XY").workplane(offset=z).transformed(rotate=(0,0,ang)).rect(c,t).wires().val()
b1=cq.Solid.makeLoft([sec(0,40,12,3),sec(50,25,10,2),sec(100,15,7,1.2)])
b2=cq.Solid.makeLoft([sec(0,40,12,3),sec(-50,25,10,2),sec(-100,15,7,1.2)])
hub=cq.Workplane("XY").transformed(rotate=(0,0,40)).rect(12,3).extrude(4,both=True)
result=cq.Workplane().add(b1).union(cq.Workplane().add(b2)).union(hub)

